import { Stack, Typography, TextField, Button, Box } from "@mui/material";

export default function LoginPage() {
  return (
    <Box
      sx={{
        height: "100vh",
        display: "flex",
        justifyContent: "center",
        alignItems: "center",
        bgcolor: "#FFE4C4", // soft peach background
      }}
    >
      <Stack
        sx={{
          p: { xs: 4, sm: 6 },
          borderRadius: 4,
          bgcolor: "#FFDAB9", // slightly darker peach card
          minWidth: { xs: "90%", sm: "400px" },
          boxShadow: "0px 4px 20px rgba(0,0,0,0.1)",
          alignItems: "center",
        }}
        spacing={3} // spacing between elements
      >
        <Typography variant="h3" sx={{ fontWeight: "bold" }}>
          Login
        </Typography>

        <TextField
          placeholder="Username"
          variant="outlined"
          fullWidth
          sx={{
            bgcolor: "white",
            borderRadius: 2,
            "& .MuiOutlinedInput-root": {
              boxShadow: "2px 2px 5px rgba(0,0,0,0.2)",
            },
          }}
        />

        <TextField
          placeholder="Password"
          type="password"
          variant="outlined"
          fullWidth
          sx={{
            bgcolor: "white",
            borderRadius: 2,
            "& .MuiOutlinedInput-root": {
              boxShadow: "2px 2px 5px rgba(0,0,0,0.2)",
            },
          }}
        />

        <Button
          variant="contained"
          sx={{
            bgcolor: "#fff",
            color: "#000",
            fontWeight: "bold",
            width: "100%",
            "&:hover": {
              bgcolor: "#f0f0f0",
            },
          }}
        >
          Sign In
        </Button>

        <Typography variant="body1">Don’t have an Account?</Typography>
        <Typography variant="body2" sx={{ cursor: "pointer" }}>
          Forgot Password?
        </Typography>
      </Stack>
    </Box>
  );
}
